for (int i = 0; i < n; i++) {
    for (int j = 0; j < n - i - 1; j++) System.out.print(" ");
    for (char ch = 'A'; ch <= 'A' + 2 * i; ch++) System.out.print(ch);
    System.out.println();
}

for (int i = 0; i < n; i++) {
    for (int j = 0; j < n - i - 1; j++) System.out.print(" ");
    char ch = 'A';
    for (int j = 0; j < 2 * i + 1; j++) {
        System.out.print(ch);
        if (j < i) ch++; else ch--;
    }
    System.out.println();
}

for (int i = 0; i < n; i++) {
    for (char ch = (char) ('A' + n - 1 - i); ch <= (char) ('A' + n - 1); ch++) {
        System.out.print(ch + " ");
    }
    System.out.println();
    System.out.println();
}

// Upper half:
for (int i = 0; i < n; i++) {
    for (int j = 0; j < n - i; j++) System.out.print("*");
    for (int j = 0; j < 2 * i; j++) System.out.print(" ");
    for (int j = 0; j < n - i; j++) System.out.print("*");
    System.out.println();
}
// Lower half:
for (int i = 0; i < n; i++) {
    for (int j = 0; j <= i; j++) System.out.print("*");
    for (int j = 0; j < 2 * (n - i - 1); j++) System.out.print(" ");
    for (int j = 0; j <= i; j++) System.out.print("*");
    System.out.println();
}

int totalRows = 2 * n - 1;
for (int i = 1; i <= totalRows; i++) {
    int stars = (i <= n) ? i : 2 * n - i;
    int spaces = 2 * (n - stars);
    for (int j = 1; j <= stars; j++) System.out.print("*");
    for (int j = 1; j <= spaces; j++) System.out.print(" ");
    for (int j = 1; j <= stars; j++) System.out.print("*");
    System.out.println();
}

for (int i = 0; i < n; i++) {
    for (int j = 0; j < n; j++) {
        if (i == 0 || j == 0 || i == n - 1 || j == n - 1) System.out.print("*");
        else System.out.print(" ");
    }
    System.out.println();
}

int size = 2 * n - 1;
for (int i = 0; i < size; i++) {
    for (int j = 0; j < size; j++) {
        int top = i, left = j, bottom = size - 1 - i, right = size - 1 - j;
        int dist = Math.min(Math.min(top, bottom), Math.min(left, right));
        System.out.print((n - dist) + " ");
    }
    System.out.println();
}
